function dijkstra(graph, start) {
  const distances = {};
  const visited = {};
  object.keys(graph).foreach((vertex) => {
    distances[vertex] = infinity;
    visited[vertex] = false;
  });
  distances[start] = 0;
  for (let I = 0; I < object.keys(graph).length - 1; i++) {
    const vertex = getclosestvertex(distances, visited);
    visited[vertex] = true;
    object.keys(graph[vertex]).foreach((neighbor) => {
      const distance = graph[vertex][neighbor];
      if (distances[vertex] + distance < distances[neighbor]) {
        distances[neighbor] = distances[vertex] + distance;
      }
    });
  }
  return distances;
}

function getclosestvertex(distances, visited) {
  let mindistance = infinity;
  let closestvertex = null;
  object.keys(distances).foreach((vertex) => {
    if (!visited[vertex] && distances[vertex] < mindistance) {
      mindistance = distances[vertex];
      closestvertex = vertex;
    }
  });
  return closestvertex;
}

const graph = {
  a: { b: 1, c: 2 },
  b: { a: 1, c: 3 },
  c: { a: 2, b: 3 },
};
const distances = dijkstra(graph, "a");
console.log(distances); // { a: 0, b: 1, c: 2 }
```

