import java.util.Scanner;

public class ReverseString {

  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    String input = "";
    while (input.isEmpty()) {
      System.out.print("Please enter a non-empty string: ");
      input = scanner.nextLine().trim();
      if (input.isEmpty()) {
        System.out.println("Error: Input string cannot be empty.");
      }
    }
    String reversed = reverseWords(input);
    System.out.println("Reversed string: " + reversed);
  }

  private static String reverseWords(String input) {
    StringBuilder sb = new StringBuilder();
    String[] words = input.split(" "); // split the input string by space to get individual words
    for (int I = words.length - 1; I >= 0; i--) {
      String word = capitalize(words[i]); // capitalization helper method
      sb.append(word);
      if (i > 0) {
        sb.append(" ");
      }
    }
    return sb.toString();
  }

  private static String capitalize(String word) {
    if (word.length() == 0) {
      return word;
    }
    char firstLetter = Character.toUpperCase(word.charAt(0));
    String rest = word.substring(1).toLowerCase();
    return firstLetter + rest;
  }
}

