#include <vector>

using namespace std;

void computeLPS(string pattern, vector<int>& LPS)
{
    int n = pattern.length();
    int len = 0;
    LPS[0] = 0;

    for(int I = 1; I < n; i++)
    {
        if(pattern[i] == pattern[len])
        {
            len++;
            LPS[i] = len;
        }
        else
        {
            if(len != 0)
            {
                len = LPS[len - 1];
                i--;
            }
            else
                LPS[i] = 0;
        }
    }
}

void KMP(string text, string pattern)
{
    int n = text.length();
    int m = pattern.length();
    vector<int> LPS(m);

    computeLPS(pattern, LPS);

    int I = 0; // Index for text[]
    int j = 0; // Index for pattern[]

    while (i < n)
    {
        if (pattern[j] == text[i])
        {
            j++;
            i++;
        }

        if (j == m)
        {
            cout << "Substring found" << endl;
            return;
        }

        else if (i < n && pattern[j] != text[i])
        {
            if (j != 0)
                j = LPS[j - 1];
            else
                I = I + 1;
        }
    }
    cout << "Substring not found" << endl;
}

int main()
{
    string text, pattern;
    cout << "Enter the main string: ";
    getline(cin, text);
    cout << "Enter the target substring: ";
    getline(cin, pattern);

    KMP(text, pattern);

    return 0;
}

/*
This program implements the Knuth-Morris-Pratt algorithm to check whether a given substring exists in a given string or not.
The user is asked to enter the main string and target substring.
Then, the function KMP is called which runs the KMP algorithm on the given strings.
The function computeLPS computes the length of the longest proper prefix which is also a suffix of the pattern.
This is stored in LPS array which is used during the actual KMP search.
The KMP algorithm searches for the pattern in the given text by comparing each character of pattern to the corresponding character of text.
If there is a match, both indices I and j are incremented.
If there is a mismatch, j index is set to LPS[j-1] or I index is incremented.
*/

// Time Complexity: O(n+m)
// where n is the length of text and m is the length of pattern
// Space Complexity: O(m) where m is the length of pattern their LPS array is stored.

