```MATLAB
% Define the system of equations
F = @(X) [ X(1)^2 + X(2)^2 + X(3)^2 - 25; 
           X(1)*X(2) + X(1)*X(3) - 8;
           X(2)*X(3) - 3 ];

% Define the Jacobian matrix
J = @(X) [ 2*X(1) 2*X(2) 2*X(3);
           X(2)+X(3) X(1) X(1);
           0 X(3) X(2) ];

% Set the initial guess, maximum number of iterations, and tolerance
X0 = [ 1; 2; 3 ];
max_iter = 100;
tol = 1e-6;

% Call the newton_raphson function to solve the system of equations
[X, iter] = newton_raphson(F, J, X0, max_iter, tol);

% Display the converged solution and number of iterations required
fprintf('Converged solution:\n');
disp(X);
fprintf('Number of iterations required: %d\n', iter);
```

